  function semanticStem(stem=''){return String(stem).toLowerCase().replace(/\d+(?:\.\d+)?/g,'#').replace(/\s+/g,' ').trim();}

  function cognitiveOperation(item){
    if(item.difficulty==='easy')return 'recall-procedure';
    const text=`${item.family||''} ${item.skill||''} ${item.stem||''}`.toLowerCase();
    if(/error|incorrect|miscalcul|flawed|best estimate/.test(text))return 'error-analysis';
    if(/model|represent|graph|table|number line|net|coordinate|display|diagram|pattern/.test(text))return 'representation-model';
    if(/multistep|multi-step|context|final cost|remainder|compound probability|elapsed|dimension|unit rate|proportion|percent/.test(text))return 'multistep-context';
    if(item.difficulty==='hard')return 'application-reasoning';
    if(item.difficulty==='medium')return 'application-reasoning';
    return 'recall-procedure';
  }
  function methodTag(item){
    if(item.praxisMethod)return item.praxisMethod;
    const t=`${item.family||''} ${item.skill||''} ${item.stem||''}`.toLowerCase();
    if(/which two|which three|select all|multiple-response/.test(t))return 'exact-set-selection';
    if(/best estimate|approximately|closest to|estimate/.test(t))return 'estimate-vs-exact';
    if(/best supported|text evidence|source|evidence/.test(t))return 'best-supported-evidence';
    if(/most appropriate|most useful|best revision|which revision|strategy/.test(t))return 'best-choice-judgment';
    if(/remainder/.test(t))return 'interpret-remainder';
    if(item.questionType==='numeric-entry')return 'numeric-entry-solve';
    if(/phoneme|syllable|phonological/.test(t))return 'literacy-unit-analysis';
    if(/variable|control|investigat|experiment/.test(t))return 'experimental-design';
    if(/graph|table|data|display/.test(t))return 'data-interpretation';
    if(/model|diagram|net|number line|coordinate|map/.test(t))return 'representation-model';
    if(/cause|chronolog|sequence/.test(t))return 'cause-chronology';
    if(/property|classif|definition|identify/.test(t))return 'recognize-classify';
    if(/error|incorrect|misconception|flawed/.test(t))return 'diagnose-error';
    return item.difficulty==='easy'?'direct-recall-procedure':'apply-content';
  }
